/* 似ている組(くらべるタブ) — ids は 動詞-小さな言葉(-後ろの語) */
sets: [
  {title:"out で「わかる」",axis:"どうやって分かる？",ids:["figure-out","find-out","work-out","puzzle-out","make-out"],note:"out の「中にあったものが外に出てくる」が「答えが出てくる＝わかる」に変わる。違いは前の動詞、つまりどうやって答えを出すか。"},
  {title:"延期？ 中止？",axis:"予定をどうする？",ids:["put-off","call-off","hold-off","put-back"],note:"off は予定から「離す」。置き直すだけ(put off)か、声をかけてなしにする(call off)かで変わる。"},
  {title:"あきらめる？ 折れる？",axis:"何を手放す？",ids:["give-up","give-in","give-away","give-out"],note:"give は「手放す」。完全に(up)手放すとあきらめ、相手の内側へ(in)手放すと屈する。"},
  {title:"目を通す",axis:"どれくらい丁寧？",ids:["look-over","go-over","look-through","go-through"],note:"over は上から全体をさっと、through は中を最初から最後まで。look は目を向けるだけ、go は一つずつたどる。"},
  {title:"乗り越える",axis:"どう抜ける？",ids:["get-over","get-through","pull-through","break-through"],note:"over は壁の上をこえる、through は中を抜ける。get は自分で移る、pull は引っ張られて、break は壊して。"},
  {title:"偶然出会う",axis:"どう出会う？",ids:["come-across","run-across","run-into"],note:"across は横切るうちに出会う。into はぶつかるように出くわす。"},
  {title:"探す・調べる",axis:"何をする？",ids:["look-for","look-up","look-into","find-out","check-out"],note:"look は目を向ける動作、find は見つけた結果。look for は物を探す、look up は情報を引く、look into は事情を探る。"},
  {title:"乗る・降りる",axis:"どんな乗り物？",ids:["get-on","get-off","get-in","get-out"],note:"立って乗る(バス・電車)は on/off、かがんで入る(車・タクシー)は in/out。"},
  {title:"after の仲間",axis:"後ろから何をする？",ids:["take-after","look-after","go-after","run-after"],note:"after は「後を追う」。後ろから受け継ぐ、後ろから見守る、後を追いかける。"},
  {title:"変わる・変える",axis:"どう変わる？",ids:["turn-into","make-into","turn-out"],note:"into は中へ入り込んで別の物になる。turn はくるっと、make は手を加えて。"},
  {title:"壊れる",axis:"どう壊れる？",ids:["break-down","break-up","fall-apart","come-apart"],note:"down は崩れ落ちる、up は完全にバラバラ、apart は分かれて離れる。"},
  {title:"現れる",axis:"どう現れる？",ids:["show-up","turn-up","come-up","come-out"],note:"up は「視界に上がってくる」。show は姿を見せる、turn はひょっこり、come は向こうからやって来る。"},
  {title:"続ける・待つ",axis:"何がくっついたまま？",ids:["go-on","carry-on","keep-on","hold-on","hang-on"],note:"on は「くっついたまま」。進み続ける、運び続ける、保ち続ける、つかみ続ける、ぶら下がり続ける。"},
  {title:"by の仲間",axis:"そばでどうする？",ids:["drop-by","come-by","stand-by","pass-by","go-by","get-by"],note:"by は「そば」。そばに寄る、そばにいる、そばを通る、そばをすり抜ける。"},
  {title:"着る・脱ぐ・片付ける",axis:"体とモノの位置は？",ids:["put-on","take-off","put-away","take-out"],note:"on は体にくっつける、off は体から離す。away は見えない所へ、out は外へ。"},
  {title:"pass の仲間",axis:"どこへ通す？",ids:["pass-on","pass-along","pass-around","pass-back","pass-over","pass-down","pass-out","pass-up","pass-by","pass-through","pass-for","pass-away"],note:"pass は「通す・通る」。手から手へ通せば「渡す・伝える」、そばを通れば「通り過ぎる」。どこへ通すかを小さな言葉が決める。"},
  {title:"pass it back？ over？ on？",axis:"どっちへ渡す？",ids:["pass-back","pass-over","pass-on","pass-along","pass-around","pass-down"],note:"back は元の人・後ろの席へ、over は間をこえて目の前の相手へ、on は次の人へ続けて、along は列に沿って、around はぐるっと全員へ、down は下の世代へ。"},
  {title:"it で「成功・失敗」",axis:"ゴールにどうする？",ids:["make-it","make-it-big","nail-it","pull-off","blow-it","wing-it"],note:"it はここでは「目指すゴール・課題・チャンス」。形にする(make)、釘を打つ(nail)、吹き飛ばす(blow)。"},
  {title:"it で「わかる・受け止める」",axis:"相手の話をどうする？",ids:["get-it","buy-it","mean-it","take-it","take-it-from-me"],note:"it は「相手の言いたいこと・話」。手に入る(get)＝わかる、買う(buy)＝信じる、心で指す(mean)＝本気。"},
  {title:"it で「やめろ・待て」",axis:"どう止める？",ids:["cut-out","knock-it-off","beat-it","hold-it","call-it-a-day","call-it-quits"],note:"it は「いまやっていること」。切り取る(cut)、叩いて外す(knock)、つかんで止める(hold)、終わりと呼ぶ(call)。"},
  {title:"it で「気持ちの持ち方」",axis:"状況をどう扱う？",ids:["take-it-easy","let-it-go","let-it-slide","play-it-safe","play-it-by-ear","lose-it","stick-with-it"],note:"it は「いまの状況・こだわり・冷静さ」。楽に受け取る、手放す、滑らせる、安全に・耳で演奏する、失う、くっつき続ける。"},
  {title:"take の仲間",axis:"どこへ取り込む？",ids:["take-in","take-out","take-over","take-down","take-up","take-on","take-off"],note:"take は「つかんで自分の側へ」。つかんだ後どこへ動くかを小さな言葉が決める。"}
]
